void Swap(BiTree T)
{
    BiTNode *t;
    if (T == NULL)
        return;
    t = T->lchild;
    T->lchild = T->rchild;
    T->rchild = t;
    Swap(T->lchild);
    Swap(T->rchild);
}

int BinSearch(int a[], int n, int key)
{
    int low = 0, high = n - 1, mid;
    while (low <= high) {
        mid = (low + high) / 2;
        if (a[mid] == key)
            return mid;
        else if (key < a[mid])
            high = mid - 1;
        else
            low = mid + 1;
    }
    return -1;
}

