void DFS(MGraph *G, int v)
{
    int w;
    printf("%d ", v);
    visited[v] = 1;
    for (w = 0; w < G->vexnum; w++)
        if (G->arcs[v][w] == 1 && !visited[w])
            DFS(G, w);
}

void DFSTraverse(MGraph *G)
{
    int v;
    for (v = 0; v < G->vexnum; v++)
        visited[v] = 0;
    for (v = 0; v < G->vexnum; v++)
        if (!visited[v])
            DFS(G, v);
}
